def is_good_triple(x, y, z):
    """
    Checks if (x, y, z) is a good triple, i.e., if x^z + 1 divides (x+1)^y.
    """
    numerator = (x + 1)**y
    denominator = x**z + 1

    if denominator == 0:
        # Since x, z are positive integers, x^z + 1 >= 1^1 + 1 = 2. This case won't happen.
        return False 

    return numerator % denominator == 0

